def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]; seen=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=7 or (r,c) in seen: continue
            area={(r,c)}; q=[(r,c)]
            for y,x in q:
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<h and 0<=b<w and grid[a][b] in (0,7) and (a,b) not in area:
                        area.add((a,b)); q.append((a,b))
            parity={(y+x)%2 for y,x in area if grid[y][x]==7}
            for y,x in area:
                if (y+x)%2 in parity: out[y][x]=7
            seen.update(area)
    return out

